# -*- coding: utf-8 -*-
"""
只读探测（需求2）：WMS 平台订单「是否偏远地区」筛选控件。
独立干净 context 登金猫(有19单，含1个偏远Y=P2AE6TCD61861)，读取：
  - 「是否偏远地区」下拉的选择器/占位符/选项
  - 选「否」+查询后 未发货数变化（期望 19 -> 18，排除偏远单）
  - 选否后剩余订单的 订单号 + 偏远列值（确认无 Y）
绝不点击 批量发货/批量修改快递方。输出 UTF-8：capture/dumps/wms_probe_remote.txt
用法：python capture/wms_probe_remote.py
"""
import sys, os, time, re
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import config
config.DRY_RUN = True
import core, secrets
from core import ORDERINFO_WMS
from playwright.sync_api import sync_playwright

JMSM = next(a for a in secrets.WMS_ACCOUNTS if a["login"] == "JMSM")

out = []
def w(s=""):
    out.append(str(s))


def total(page):
    el = page.query_selector(".el-pagination__total")
    if el:
        m = re.findall(r"\d+", el.inner_text() or "")
        if m:
            return int(m[0])
    return None


def query(page):
    try:
        page.click("button:has-text('查询')", timeout=6000); time.sleep(3)
    except Exception as e:
        w(f"  点查询失败: {e}")


def rows_far(page):
    """读每行 订单号 + 是否偏远地区列值。表头[9]=是否偏远地区。"""
    return page.evaluate(r"""() => {
      const heads=[...document.querySelectorAll('.el-table__header-wrapper thead th')].map(th=>th.innerText.trim());
      const far=heads.findIndex(h=>h.includes('偏远'));
      const res=[];
      document.querySelectorAll('.el-table__body-wrapper tr.el-table__row').forEach(tr=>{
        const tds=[...tr.querySelectorAll('td')];
        const txt=(tr.innerText||'');
        const m=txt.match(/P[0-9A-Z]{9,15}/);
        const farv = far>=0 && tds[far] ? tds[far].innerText.trim() : '?';
        if(m) res.push(m[0]+':'+farv);
      });
      return {far_col_index: far, rows: [...new Set(res)]};
    }""")


def dump_control(page):
    """dump 含'偏远'的筛选控件结构。"""
    return page.evaluate(r"""() => {
      const out=[];
      document.querySelectorAll('.el-select, .el-input').forEach(g=>{
        const inp=g.querySelector('input');
        if(!inp) return;
        const ph=inp.getAttribute('placeholder')||'';
        if(ph.includes('偏远')) out.push({placeholder: ph, value: inp.value||'', cls: g.className});
      });
      return out;
    }""")


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True, args=["--no-sandbox"])
        ctx = browser.new_context(ignore_https_errors=True)
        page = ctx.new_page()
        try:
            core.wms_login(page, JMSM)
            core.safe_goto(page, ORDERINFO_WMS); time.sleep(4)
            query(page)
            w(f"未发货(初始) total = {total(page)}")
            w(f"偏远筛选控件 = {dump_control(page)}")

            # 打开「是否偏远地区」下拉，dump 选项
            inp = page.query_selector("input[placeholder*='偏远']")
            w(f"input[placeholder*='偏远'] 命中 = {bool(inp)}")
            if inp:
                inp.click(); time.sleep(1.2)
                items = [ (o.inner_text() or "").strip() for o in page.query_selector_all(".el-select-dropdown__item") if o.is_visible() ]
                w(f"下拉可见选项 = {items}")
                # 选「否」
                picked = False
                for o in page.query_selector_all(".el-select-dropdown__item"):
                    if o.is_visible() and (o.inner_text() or "").strip() == "否":
                        o.click(); picked = True; break
                w(f"选中「否」= {picked}")
                time.sleep(1)
                query(page)
                w(f"未发货(选否后) total = {total(page)}")
                w(f"选否后订单(号:偏远列) = {rows_far(page)}")
        finally:
            ctx.close(); browser.close()

    path = os.path.join(config.DUMP_DIR, "wms_probe_remote.txt")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    print("WROTE", path)


if __name__ == "__main__":
    main()

